<?php use App\Core\CSRF; ?>
<div class="mb-4"><h1 class="h3 mb-1">Configurações Automotivas</h1><p class="text-secondary mb-0">Agenda por box, materiais técnicos, etapas e CRM.</p></div>
<div class="row g-4"><div class="col-lg-5"><div class="card mb-4"><div class="card-header"><strong>Operação</strong></div><div class="card-body"><form method="post" action="/auto/settings" class="row g-3"><?=CSRF::field()?><div class="col-6"><label class="form-label">Intervalo dos slots</label><input type="number" min="5" max="120" name="slot_interval_minutes" value="<?=(int)($settings['slot_interval_minutes']??30)?>" class="form-control"></div><div class="col-6"><label class="form-label">Buffer padrão</label><input type="number" min="0" max="240" name="default_buffer_minutes" value="<?=(int)($settings['default_buffer_minutes']??10)?>" class="form-control"></div><div class="col-12"><label class="form-label">Retorno CRM padrão (dias)</label><input type="number" min="1" max="730" name="crm_default_return_days" value="<?=(int)($settings['crm_default_return_days']??30)?>" class="form-control"></div><div class="col-12 form-check ms-2"><input class="form-check-input" type="checkbox" name="public_enabled" value="1" id="pub" <?=($settings['public_enabled']??1)?'checked':''?>><label class="form-check-label" for="pub">Reserva pública Auto ativa</label></div><div class="col-12 form-check ms-2"><input class="form-check-input" type="checkbox" name="require_checkin_photos" value="1" id="photos" <?=!empty($settings['require_checkin_photos'])?'checked':''?>><label class="form-check-label" for="photos">Exigir fotos de entrada por procedimento interno</label></div><div class="col-12 form-check ms-2"><input class="form-check-input" type="checkbox" name="require_delivery_acceptance" value="1" id="termsReq" <?=!empty($settings['require_delivery_acceptance'])?'checked':''?>><label class="form-check-label" for="termsReq">Exigir aceite de entrega</label></div><div class="col-12"><label class="form-label">Termos de entrega/recebimento</label><textarea name="terms_text" rows="5" class="form-control"><?=htmlspecialchars($settings['terms_text']??'')?></textarea></div><div class="col-12"><button class="btn btn-primary">Salvar configurações</button></div></form></div></div>
<div class="card"><div class="card-header"><strong>Etapas técnicas por serviço</strong></div><div class="card-body"><form method="post" action="/auto/settings/steps" class="row g-2 mb-3"><?=CSRF::field()?><div class="col-12"><select name="service_id" class="form-select" required><option value="">Serviço</option><?php foreach($services as $s):?><option value="<?=(int)$s['id']?>"><?=htmlspecialchars($s['name'])?></option><?php endforeach;?></select></div><div class="col-6"><input name="name" class="form-control" placeholder="Ex.: Cura da vitrificação" required></div><div class="col-6"><select name="step_type" class="form-select"><option value="preparation">Preparação</option><option value="service">Execução</option><option value="drying">Secagem</option><option value="curing">Cura</option><option value="quality">Qualidade</option><option value="delivery">Entrega</option><option value="other">Outra</option></select></div><div class="col-6"><input type="number" name="expected_minutes" class="form-control" placeholder="Minutos"></div><div class="col-6"><input type="number" name="sort_order" class="form-control" placeholder="Ordem"></div><div class="col-12"><button class="btn btn-outline-primary">Adicionar etapa</button></div></form><div class="list-group"><?php foreach($steps as $st):?><div class="list-group-item"><strong><?=htmlspecialchars($st['service_name'])?></strong> · <?=htmlspecialchars($st['name'])?> <small class="text-secondary">(<?=htmlspecialchars($st['step_type'])?>)</small></div><?php endforeach;?></div></div></div></div>
<div class="col-lg-7"><div class="card"><div class="card-header"><strong>Materiais consumidos automaticamente</strong></div><div class="card-body"><p class="text-secondary">Ao fechar a comanda, o estoque pode baixar shampoo, cera, coating, composto e demais materiais vinculados ao serviço.</p><form method="post" action="/auto/settings/materials" class="row g-2 mb-3"><?=CSRF::field()?><div class="col-md-5"><select name="service_id" class="form-select" required><option value="">Serviço</option><?php foreach($services as $s):?><option value="<?=(int)$s['id']?>"><?=htmlspecialchars($s['name'])?></option><?php endforeach;?></select></div><div class="col-md-5"><select name="product_id" class="form-select" required><option value="">Produto/material</option><?php foreach($products as $p):?><option value="<?=(int)$p['id']?>"><?=htmlspecialchars($p['name'])?> (<?=htmlspecialchars($p['unit'])?>)</option><?php endforeach;?></select></div><div class="col-md-2"><input name="quantity" step="0.001" type="number" min="0.001" class="form-control" placeholder="Qtd." required></div><div class="col-12"><button class="btn btn-outline-primary">Vincular material</button></div></form><div class="table-responsive"><table class="table"><thead><tr><th>Serviço</th><th>Material</th><th>Consumo</th><th></th></tr></thead><tbody><?php foreach($materials as $m):?><tr><td><?=htmlspecialchars($m['service_name'])?></td><td><?=htmlspecialchars($m['product_name'])?></td><td><?=number_format((float)$m['quantity'],3,',','.')?> <?=htmlspecialchars($m['unit'])?></td><td><form method="post" action="/auto/settings/materials/remove"><?=CSRF::field()?><input type="hidden" name="service_id" value="<?=(int)$m['service_id']?>"><input type="hidden" name="product_id" value="<?=(int)$m['product_id']?>"><button class="btn btn-sm btn-outline-danger">Remover</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div>
